+        release: bakeOpen([new THREE.Vector3(-0.26, 0.7, 0), new THREE.Vector3(0.15, 0.98, -0.14), new THREE.Vector3(0.85, 1.2, -0.18)]),
+      },
+      heat: {
+        absorb: bakeOpen([new THREE.Vector3(0.95, 0.4, 0.28), new THREE.Vector3(0.15, 0.42, 0.14), new THREE.Vector3(-0.24, 0.55, 0)]),
+        release: bakeOpen([new THREE.Vector3(-0.5, 0.78, 0), new THREE.Vector3(-0.85, 1.0, 0.16), new THREE.Vector3(-1.4, 1.18, 0.28)]),
+      },
+    },
+  };
+
+  const IN_S = new THREE.Vector3(-0.28, 2.02, 0);
+  const OUT_S = new THREE.Vector3(1.32, 0.42, 0);
+  const COMP_S = new THREE.Vector3(0.98, 0.3, 0.04);
+  const IN_M = new THREE.Vector3(-0.5, 0.72, 0.02);
+  const OUT_M = new THREE.Vector3(-0.26, 0.64, 0);
+  const COMP_M = new THREE.Vector3(-0.42, 0.26, 0.04);
+
+  function heatAt(p, indoor, outdoor, comp, mode) {
+    const wIn = 1 / (p.distanceToSquared(indoor) + 0.02);
+    const wOut = 1 / (p.distanceToSquared(outdoor) + 0.02);
+    const wC = 1 / (p.distanceToSquared(comp) + 0.05);
+    const inH = mode === 'cool' ? 0.08 : 1;
+    const outH = mode === 'cool' ? 1 : 0.08;
+    return (wIn * inH + wOut * outH + wC * 0.7) / (wIn + wOut + wC);
+  }
+  function packHeat(bake, indoor, outdoor, comp) {
+    bake.hCool = bake.pos.map((p) => heatAt(p, indoor, outdoor, comp, 'cool'));
+    bake.hHeat = bake.pos.map((p) => heatAt(p, indoor, outdoor, comp, 'heat'));
+  }
+  packHeat(splitBake, IN_S, OUT_S, COMP_S);
+  packHeat(monoBake, IN_M, OUT_M, COMP_M);
+
+  function makePoints(count, size, blending) {
+    const geo = new THREE.BufferGeometry();
+    const pos = new Float32Array(count * 3);
+    const col = new Float32Array(count * 3);
+    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
+    geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
+    const mat = new THREE.PointsMaterial({
+      size, vertexColors: true, map: sprite, transparent: true, depthWrite: false,
+      blending, sizeAttenuation: true, opacity: 0.92,
