+    const pts = new THREE.Points(geo, mat);
+    pts.frustumCulled = false;
+    pts.renderOrder = 3;
+    scene.add(pts);
+    const offsets = new Float32Array(count);
+    for (let i = 0; i < count; i++) offsets[i] = Math.random();
+    return { geo, pos, col, count, offsets };
+  }
+  const refPts = makePoints(100, 13, THREE.NormalBlending);
+  const roomPts = makePoints(150, 11, THREE.NormalBlending);
+  const outPts = makePoints(130, 11, THREE.NormalBlending);
+  const heatPts = makePoints(70, 18, THREE.AdditiveBlending);
+
+  const ROOM = new THREE.Color('#e7d5c3');
+  const ROOM_COOL = new THREE.Color('#c5d7ea');
+  const ROOM_HOT = new THREE.Color('#f0c8aa');
+  const OUT = new THREE.Color('#8fd0c8');
+  const OUT_HOT = new THREE.Color('#e7c9a4');
+  const OUT_COLD = new THREE.Color('#a9c4e0');
+  const REF = new THREE.Color('#9a8cff');
+  const HEAT_C = new THREE.Color('#ffb15a');
+  const tmp = new THREE.Color();
+
+  addTag('Indoor coil', new THREE.Vector3(-0.62, 2.28, 0.35), 'split');
+  addTag('Outdoor coil', new THREE.Vector3(1.55, 0.62, 0.28), 'split');
+  addTag('Compressor', new THREE.Vector3(0.78, 0.16, 0.28), 'split');
+  addTag('Expansion', new THREE.Vector3(-0.62, 1.72, 0.42), 'split');
+  addTag('Reversing valve', new THREE.Vector3(1.28, 0.66, 0.36), 'split');
+  addTag('Indoor fan', new THREE.Vector3(-0.62, 1.95, -0.35), 'split');
+  addTag('Outdoor fan', new THREE.Vector3(1.45, 0.95, 0.36), 'split');
+  addTag('Refrigerant line', new THREE.Vector3(0.2, 1.38, 0.48), 'split');
+  addTag('Indoor coil', new THREE.Vector3(-0.78, 0.78, 0.4), 'mono');
+  addTag('Outdoor coil', new THREE.Vector3(-0.2, 0.58, 0.42), 'mono');
+  addTag('Compressor', new THREE.Vector3(-0.72, 0.18, 0.38), 'mono');
+  addTag('Expansion', new THREE.Vector3(-0.72, 1.12, 0.15), 'mono');
+  addTag('Reversing valve', new THREE.Vector3(-0.55, 0.52, 0.4), 'mono');
+  addTag('Indoor fan', new THREE.Vector3(-0.82, 0.95, 0.32), 'mono');
+  addTag('Outdoor fan', new THREE.Vector3(0.15, 1.16, 0.05), 'mono');
+  addTag('Intake', new THREE.Vector3(0.72, 0.58, 0.28), 'mono');
+  addTag('Exhaust', new THREE.Vector3(0.75, 1.18, -0.28), 'mono');
+  addTag('Air barrier', new THREE.Vector3(-0.55, 1.18, 0.4), 'mono');
+  const condTag = addTag('Condensation', new THREE.Vector3(-0.55, 1.62, 0.2), 'cond', 'cold');
+  const absorbTag = addTag('Heat absorbed', new THREE.Vector3(-0.7, 2.2, 0.45), 'dyn', 'cold');
+  const releaseTag = addTag('Heat released', new THREE.Vector3(1.55, 1.15, 0.4), 'dyn', 'hot');
+
+  function setScenario(mode) {
+    if (mode === 'cool') {
+      temp.inn = 27.4; temp.innTarget = 22.2; temp.out = 31.2; temp.outTarget = 32.6;
+    } else {
+      temp.inn = 16.6; temp.innTarget = 22.5; temp.out = 8.0; temp.outTarget = 5.8;
+    }
+  }
+
+  function applyCaption() {
+    if (guide) return;
+    tutText.textContent = CAP[state.system + '|' + state.mode];
+    dots.hidden = true;
+  }
+
+  function applyState() {
+    split.visible = state.system === 'split';
+    mono.visible = state.system === 'mono';
+    const cool = state.mode === 'cool';
+    indoorCoilMat.emissive.set(cool ? 0x1a4d8a : 0xc4622d);
+    outdoorCoilMat.emissive.set(cool ? 0xc4622d : 0x1a4d8a);
+    indoorCoilMat.userData.baseEm = cool ? 0.5 : 0.42;
+    outdoorCoilMat.userData.baseEm = cool ? 0.42 : 0.5;
+    indoorCoilMat.emissiveIntensity = indoorCoilMat.userData.baseEm;
+    outdoorCoilMat.emissiveIntensity = outdoorCoilMat.userData.baseEm;
+    exhaustMat.emissive.set(cool ? 0xc4622d : 0x2a5f99);
+    exhaustMat.userData.baseEm = 0.32;
+    exhaustMat.emissiveIntensity = 0.32;
+    const sysName = state.system === 'split' ? 'Split system' : 'Monoblock';
+    const modeName = cool ? 'Cooling' : 'Heating';
+    $('stateLine').textContent = sysName + ' · ' + modeName;
+    $('absorb').textContent = cool ? 'Indoor coil' : 'Outdoor coil';
+    $('release').textContent = cool ? 'Outdoor coil' : 'Indoor coil';
+    document.querySelectorAll('#segSystem button').forEach((b) => {
+      b.setAttribute('aria-pressed', String(b.dataset.system === state.system));
+    });
+    document.querySelectorAll('#segMode button').forEach((b) => {
+      b.setAttribute('aria-pressed', String(b.dataset.mode === state.mode));
+    });
+    const key = state.system + '|' + state.mode;
+    dropGroups.forEach((d) => { d.g.visible = d.key === key; });
+    labels.forEach(({ obj, bucket }) => {
+      const show = bucket === 'dyn' || bucket === 'cond' || bucket === state.system;
+      obj.element.style.display = show ? '' : 'none';
+    });
+    if (state.system === 'split') {
+      absorbTag.position.copy(cool ? new THREE.Vector3(-0.72, 2.24, 0.42) : new THREE.Vector3(1.62, 0.78, 0.4));
+      releaseTag.position.copy(cool ? new THREE.Vector3(1.55, 1.2, 0.4) : new THREE.Vector3(-0.75, 2.22, 0.4));
+      condTag.position.copy(cool ? new THREE.Vector3(-0.58, 1.68, 0.28) : new THREE.Vector3(1.55, 0.16, 0.32));
+    } else {
+      absorbTag.position.copy(cool ? new THREE.Vector3(-0.88, 0.95, 0.42) : new THREE.Vector3(0.85, 0.62, 0.36));
+      releaseTag.position.copy(cool ? new THREE.Vector3(0.9, 1.28, -0.05) : new THREE.Vector3(-0.9, 1.12, 0.36));
+      condTag.position.copy(cool ? new THREE.Vector3(-0.78, 0.42, 0.36) : new THREE.Vector3(-0.12, 0.38, 0.4));
+    }
+    applyCaption();
+  }
+
+  function renderDots() {
+    dots.hidden = false;
+    dots.innerHTML = '';
+    GUIDE.forEach((_, i) => {
+      const s = document.createElement('span');
+      if (guide && i === guide.i) s.className = 'on';
+      dots.appendChild(s);
+    });
+  }
+
+  function applyGuideStep() {
+    const step = GUIDE[guide.i];
+    const prevMode = state.mode;
+    if (step.system) state.system = step.system;
+    if (step.mode) state.mode = step.mode;
+    state.highlight = step.highlight || null;
+    if (step.mode !== prevMode) setScenario(step.mode);
+    applyState();
+    tutText.textContent = step.text;
+    renderDots();
+  }
+
+  function stopGuide() {
+    guide = null;
+    state.highlight = null;
+    guideBtn.setAttribute('aria-pressed', 'false');
+    applyCaption();
+  }
+
+  function startGuide() {
+    guide = { i: 0, left: GUIDE[0].dur };
+    guideBtn.setAttribute('aria-pressed', 'true');
+    const prev = state.mode;
+    applyGuideStep();
+    if (GUIDE[0].mode !== prev) setScenario(GUIDE[0].mode);
+  }
+
+  $('segSystem').addEventListener('click', (e) => {
+    const b = e.target.closest('button');
+    if (!b) return;
+    state.system = b.dataset.system;
+    stopGuide();
+    applyState();
+  });
+  $('segMode').addEventListener('click', (e) => {
+    const b = e.target.closest('button');
+    if (!b) return;
+    if (b.dataset.mode !== state.mode) {
+      state.mode = b.dataset.mode;
+      setScenario(state.mode);
+    }
+    stopGuide();
+    applyState();
+  });
+  playBtn.addEventListener('click', () => {
+    state.playing = !state.playing;
+    playBtn.textContent = state.playing ? 'Pause' : 'Play';
+    playBtn.setAttribute('aria-pressed', String(state.playing));
+  });
+  $('resetBtn').addEventListener('click', () => controls.reset());
+  guideBtn.addEventListener('click', startGuide);
+
+  const HL = {
+    loop: [pipeMat],
+    indoor: [indoorCoilMat],
+    valve: [valveMat],
+    ducts: [ductMat, exhaustMat],
+    compressor: [compMat],
+  };
+
+  function sampleBake(bake, t) {
+    const idx = Math.min(bake.n - 1, Math.floor(t * bake.n));
+    return bake.pos[idx];
+  }
+
+  function writeStream(cloud, bake, speed, paint) {
+    const { pos, col, count, offsets } = cloud;
+    for (let i = 0; i < count; i++) {
+      let t = (simTime * speed + offsets[i]) % 1;
+      if (t < 0) t += 1;
+      const p = sampleBake(bake, t);
+      pos[i * 3] = p.x;
+      pos[i * 3 + 1] = p.y;
+      pos[i * 3 + 2] = p.z;
+      paint(t, i, tmp);
+      col[i * 3] = tmp.r;
+      col[i * 3 + 1] = tmp.g;
+      col[i * 3 + 2] = tmp.b;
+    }
+    cloud.geo.attributes.position.needsUpdate = true;
+    cloud.geo.attributes.color.needsUpdate = true;
+  }
+
+  let uiAcc = 0;
+  const clock = new THREE.Clock();
+  playBtn.textContent = state.playing ? 'Pause' : 'Play';
+  playBtn.setAttribute('aria-pressed', String(state.playing));
+  setScenario('cool');
+  applyState();
+
+  function frame() {
+    const dt = Math.min(clock.getDelta(), 0.05);
+    if (state.playing) {
+      simTime += dt;
+      temp.inn += (temp.innTarget - temp.inn) * Math.min(1, dt * 0.28);
+      temp.out += (temp.outTarget - temp.out) * Math.min(1, dt * 0.35);
+      spinners.forEach((s) => { s.obj.rotation.y += dt * s.speed; });
+      if (guide) {
+        guide.left -= dt;
+        if (guide.left <= 0) {
+          guide.i += 1;
+          if (guide.i >= GUIDE.length) stopGuide();
+          else {
+            guide.left = GUIDE[guide.i].dur;
+            applyGuideStep();
+          }
+        }
+      }
+    }
+    const nudge = state.mode === 'cool' ? -0.045 : 0.045;
+    valveShown += (nudge - valveShown) * Math.min(1, dt * 4);
+    valveNubs.forEach((n) => { n.position.x = valveShown; });
+
+    dropGroups.forEach((d) => {
+      if (!d.g.visible) return;
+      d.g.children.forEach((m) => {
+        const u = (simTime * 0.22 + m.userData.phase) % 1;
+        m.position.y = m.userData.baseY - u * 0.16;
+        const s = 0.45 + u * 0.7;
+        m.scale.setScalar(s);
+      });
+    });
+
+    const refBake = state.system === 'split' ? splitBake : monoBake;
+    const dir = state.mode === 'heat' ? -1 : 1;
+    const heats = state.mode === 'heat' ? refBake.hHeat : refBake.hCool;
+    writeStream(refPts, refBake, 0.055 * dir, (t) => {
+      const idx = Math.min(refBake.n - 1, Math.floor((((t % 1) + 1) % 1) * refBake.n));
+      const h = heats[idx];
+      tmp.copy(REF).multiplyScalar(0.72 + h * 0.5);
+    });
+    const air = state.system === 'split' ? A_SPLIT : A_MONO;
+    const mode = state.mode;
+    writeStream(roomPts, air.room, 0.07, (t) => {
+      const fresh = t < 0.24 ? 1 : Math.max(0, 1 - (t - 0.24) / 0.5);
+      tmp.copy(ROOM).lerp(mode === 'cool' ? ROOM_COOL : ROOM_HOT, fresh * 0.82);
+    });
+    writeStream(outPts, air.out, 0.065, (t) => {
+      const fresh = t < 0.24 ? 1 : Math.max(0, 1 - (t - 0.24) / 0.5);
+      tmp.copy(OUT).lerp(mode === 'cool' ? OUT_HOT : OUT_COLD, fresh * 0.82);
+    });
+    const paths = HEAT[state.system][state.mode];
+    const half = heatPts.count / 2;
+    for (let i = 0; i < heatPts.count; i++) {
+      const absorb = i < half;
+      const bake = absorb ? paths.absorb : paths.release;
+      const t = (simTime * 0.28 + heatPts.offsets[i]) % 1;
+      const p = sampleBake(bake, t);
+      heatPts.pos[i * 3] = p.x;
+      heatPts.pos[i * 3 + 1] = p.y;
+      heatPts.pos[i * 3 + 2] = p.z;
+      const fade = Math.sin(Math.max(0, Math.min(1, t)) * Math.PI);
+      tmp.copy(HEAT_C).multiplyScalar(fade);
+      heatPts.col[i * 3] = tmp.r;
+      heatPts.col[i * 3 + 1] = tmp.g;
+      heatPts.col[i * 3 + 2] = tmp.b;
+    }
+    heatPts.geo.attributes.position.needsUpdate = true;
+    heatPts.geo.attributes.color.needsUpdate = true;
+
+    const pulse = state.highlight ? 0.28 + Math.sin(simTime * 5) * 0.22 : 0;
+    Object.keys(HL).forEach((name) => {
+      const on = state.highlight === name;
+      HL[name].forEach((m) => {
+        m.emissiveIntensity = (m.userData.baseEm || 0) + (on ? pulse : 0);
+      });
+    });
+
+    uiAcc += dt;
+    if (uiAcc > 0.12) {
+      uiAcc = 0;
+      $('tIn').textContent = temp.inn.toFixed(1) + '°C';
+      $('tOut').textContent = temp.out.toFixed(1) + '°C';
+    }
+
+    controls.update();
+    renderer.render(scene, camera);
+    labelRenderer.render(scene, camera);
+    requestAnimationFrame(frame);
+  }
+
+  window.addEventListener('resize', () => {
+    camera.aspect = window.innerWidth / window.innerHeight;
+    camera.updateProjectionMatrix();
+    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, window.innerWidth < 800 ? 1.5 : 2));
+    renderer.setSize(window.innerWidth, window.innerHeight);
+    labelRenderer.setSize(window.innerWidth, window.innerHeight);
+  });
+  canvas.addEventListener('webglcontextlost', (e) => {
+    e.preventDefault();
+    fail('WebGL stopped. Reload the page to restart the exhibit.');
+  }, false);
+
+  frame();
+}
+</script>
+</body>
+</html>

